  ".timeline-row{display:grid;grid-template-columns:42px 1fr;gap:10px;padding:13px 0;border-bottom:1px solid rgba(184,145,60,.07);}",
  ".timeline-num{font-family:var(--serif);font-size:28px;font-weight:300;color:rgba(184,145,60,.1);line-height:1;}",
  ".timeline-title{font-family:var(--serif);font-size:13px;color:var(--cr);margin-bottom:2px;font-weight:400;}",
  ".timeline-sub{font-size:11.5px;color:rgba(245,239,227,.32);line-height:1.82;font-weight:300;}",
  ".story-mid{display:grid;grid-template-columns:1fr 1fr;}",
  ".story-dark{background:var(--g);padding:68px 72px;display:flex;flex-direction:column;justify-content:center;}",
  ".story-light{background:var(--cr2);display:flex;align-items:center;justify-content:center;padding:52px;}",
  ".blockquote{border-left:2px solid rgba(184,145,60,.18);padding-left:15px;font-family:var(--serif);font-style:italic;font-size:16px;line-height:1.65;color:rgba(245,239,227,.22);margin-top:26px;}",
  ".contact-split{display:grid;grid-template-columns:1fr 1fr;}",
  ".contact-dark{background:var(--g);padding:76px 72px;display:flex;flex-direction:column;justify-content:center;}",
  ".contact-light{background:var(--cr2);padding:76px 72px;}",
  ".contact-label{font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:3px;opacity:.82;}",
  ".contact-val{font-size:14px;color:rgba(245,239,227,.8);margin-bottom:14px;font-weight:300;}",
  ".customize-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start;}",
  ".stone-picker{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;}",
  ".stone-pill{background:var(--cr2);border:1px solid rgba(26,18,10,.1);padding:9px 4px;text-align:center;cursor:pointer;transition:all .18s;display:flex;flex-direction:column;align-items:center;gap:2px;}",
  ".stone-pill:hover{border-color:rgba(184,145,60,.35);}",
  ".stone-pill.picked{background:var(--g);border-color:var(--g);}",
  ".stone-pill-name{font-size:8px;color:var(--ink3);}",
  ".stone-pill.picked .stone-pill-name{color:var(--gold);}",
  ".stone-pill-meaning{font-size:6.5px;color:var(--ink3);opacity:.6;}",
  ".stone-pill.picked .stone-pill-meaning{color:rgba(184,145,60,.44);}",
  ".estimate-box{background:var(--cr2);padding:15px;margin-bottom:14px;border-left:2px solid var(--gold);}",
  ".estimate-row{display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid rgba(26,18,10,.07);}",
  ".estimate-key{color:var(--ink3);font-weight:300;}",
  ".estimate-val{color:var(--ink);}",
  ".estimate-total{display:flex;justify-content:space-between;align-items:center;margin-top:10px;}",
  ".estimate-total-val{font-family:var(--serif);font-size:24px;color:var(--ink);}",
  ".craft-note{background:var(--cr3);padding:10px 12px;margin-top:10px;}",
  ".craft-note p{font-size:11px;color:var(--ink3);line-height:1.82;font-weight:300;}",
  ".success-block{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:44vh;gap:14px;text-align:center;padding:40px;}",
  ".success-icon{font-family:var(--serif);font-size:40px;color:var(--gold);}",
  ".success-title{font-family:var(--serif);font-size:26px;font-weight:300;color:var(--ink);}",
  ".care-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;}",
  ".care-step{background:var(--cr2);padding:22px 18px;border-top:2px solid transparent;transition:border-top-color .28s,transform .35s var(--ease);}",
  ".care-step:hover{border-top-color:var(--gold);}",
  ".care-step-icon{font-family:var(--serif);font-size:17px;color:var(--gold);margin-bottom:9px;opacity:.6;}",
  ".care-step-title{font-family:var(--serif);font-size:13px;color:var(--ink);margin-bottom:4px;}",
  ".care-step-text{font-size:11px;color:var(--ink3);line-height:1.75;font-weight:300;}",
  "@media(max-width:1024px){",
  ".nav-links{display:none!important;}",
  ".ham{display:flex;}",
  ".nav{padding:0 20px;height:56px;}",
  ".hero{grid-template-columns:1fr;}",
  ".hero-l{padding:80px 20px 48px;}",
  ".hero-img{display:none;}",
  ".page-header{padding:90px 20px 44px;}",
  ".section,.section-cream,.section-cream2,.section-dark,.section-dark2{padding:48px 20px;}",
  "@media(max-width:680px){.detail-layout{grid-template-columns:1fr;}}",
  "@media(max-width:680px){.detail-info{padding:24px 20px;}}",
  ".story-split,.story-mid,.contact-split,.customize-grid{grid-template-columns:1fr;}",
  ".story-right,.story-light{display:none;}",
  ".story-left,.story-dark,.contact-dark,.contact-light{padding:52px 20px;}",
  ".how-grid{grid-template-columns:1fr 1fr;}",
  ".promise-strip{grid-template-columns:1fr 1fr;}",
  ".care-steps{grid-template-columns:1fr 1fr;}",
  ".footer-grid{grid-template-columns:1fr 1fr;gap:24px;}",
  ".footer{padding:44px 20px 22px;}",
  ".footer-bottom{flex-direction:column;gap:5px;}",
  ".cart-drawer{width:100%;}",
  ".search-drop{padding:13px 20px;}",
  ".field-grid{grid-template-columns:1fr;}",
  "}",
  "/* Horizontal carousel */",
  "div[style*='scrollSnapType']{-ms-overflow-style:none;scrollbar-width:none;}",
  "div[style*='scrollSnapType']::-webkit-scrollbar{display:none;}",
